import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Développement de plugins","description":"Guide technique pour les développeurs de plugins ATLAS.","frontmatter":{"title":"Développement de plugins","description":"Guide technique pour les développeurs de plugins ATLAS."},"headers":[],"relativePath":"fr/projects/atlas-plugins/developers/index.md","filePath":"fr/projects/atlas-plugins/developers/index.md","lastUpdated":1793118610000}'),n={name:"fr/projects/atlas-plugins/developers/index.md"};function l(r,e,o,u,d,p){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="developpement-de-plugins" tabindex="-1">Développement de plugins <a class="header-anchor" href="#developpement-de-plugins" aria-label="Permalink to &quot;Développement de plugins&quot;">​</a></h1><p>Cette rubrique présente le parcours de création d&#39;un plugin ATLAS autonome, du projet de départ au manifeste, au Runtime et à la publication. Les contrats évoluent encore ; vérifiez le modèle et le format de dépôt actuels avant toute publication.</p><h2 id="parcours-recommande" tabindex="-1">Parcours recommandé <a class="header-anchor" href="#parcours-recommande" aria-label="Permalink to &quot;Parcours recommandé&quot;">​</a></h2><ol><li>Créez un dépôt à partir du <a href="./../plugin-template">modèle officiel de plugin</a>.</li><li>Choisissez un identifiant unique et stable, puis renseignez le nom, la version, la description, les ressources et les capacités nécessaires dans le manifeste.</li><li>Développez d&#39;abord l&#39;interface du plugin de manière indépendante. Le modèle actuel contient une petite page d&#39;exemple en HTML/CSS/JavaScript.</li><li>Générez le paquet et le catalogue avec <code>npm run build</code>, puis vérifiez-les avec <code>npm run check</code>.</li><li>Testez le catalogue via le dépôt de démonstration ATLAS ou l&#39;Administration. Augmentez la version du plugin pour chaque modification publiée.</li></ol><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><ul><li><a href="./compatibility">Versions et compatibilité</a> : règles de publication, limites vérifiées, sauvegardes et migrations.</li><li><a href="./manifest">Manifeste et capacités</a> : métadonnées, identifiants, versions, ressources et déclarations.</li><li><a href="./runtime">Runtime et cycle de vie</a> : contrat Runtime et activation, désactivation et nettoyage.</li><li><a href="./publishing">Construire, valider et publier</a> : générateur de paquet, catalogue, GitHub Actions et liste de contrôle.</li><li><a href="./../plugin-template">Modèle de plugin</a> : guide pas à pas du dépôt de démarrage GitHub.</li><li><a href="./../repository-format">Format du dépôt</a> : champs du catalogue et format du paquet installable.</li></ul><h2 id="limites-de-securite" tabindex="-1">Limites de sécurité <a class="header-anchor" href="#limites-de-securite" aria-label="Permalink to &quot;Limites de sécurité&quot;">​</a></h2><p>Déclarez uniquement les capacités réellement utilisées par votre plugin. Une déclaration décrit son objectif ; ce n&#39;est ni une sandbox ni un accès automatique à Home Assistant ou aux composants internes d&#39;Atlas. Ne demandez pas d&#39;identifiants dans les fichiers du plugin et ne publiez jamais de jeton ni de clé API.</p><p>Le serveur App installe les paquets validés, depuis un dépôt ou un import, dans le stockage persistant et sert les fichiers web sous <code>/plugin-assets/&lt;slug&gt;/</code>. Leur JavaScript s’exécute dans le navigateur à l’ouverture ; les modules Node ou hooks Runtime ne sont pas enregistrés automatiquement. Ce n’est pas une sandbox : vérifier paquet et code avant ouverture.</p>',9)])])}const g=t(n,[["render",l]]);export{m as __pageData,g as default};
